  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0321$t$, $t$Medford Lakes Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Medford Lakes Fire Department, Bureau of Fire Prevention (LEA #03321) (town fire bureau)","Contact: Vincent Knott, Fire Official · (856) 316-8584 · vincent.knott@mlfd371.org","Apply: Submit to the Borough Office more than 10 business days before settlement to avoid higher fees. The Fire Official contacts the applicant once the paid application is received. The October 2024 form says certificates are valid for 90 days; the Borough web page says six months.","How to apply: Fill out the Application for Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (address, block and lot, owner, occupant, sales agent and firm, settlement date) and submit it with the fee, payable to the Borough of Medford Lakes, to the Borough Office at 1 Cabin Circle. The form records cash or check; the web page says cash or money order. The Fire Official then calls to schedule.","Fire official in the NJ state directory (town), updated 5/18/2026: Craig Farnsworth II · (609) 654-8898 · craig.farnsworth@mlfd371.org","House numbers: numerals at least 4 inches high, contrasting color, permanently fixed to the house and visible from the street; light post or mailbox numbers are not accepted","Smoke alarm on every level; basement alarm at the bottom of the stairwell at ceiling level (not between joists); hallway alarm within 10 feet of all bedroom doors","Smoke alarm on the ceiling of every bedroom in homes built 1991 to present","Hard-wired smoke alarms cannot be replaced with battery alarms; all smoke alarms under 10 years old and working; battery alarms must be the 10-year battery type","CO alarm in the hallway within 10 feet of all bedrooms, under 10 years old, installed per the maker; plug-in, battery or hard-wired accepted, but not in switched outlets or against floor molding","Fire extinguisher still on the October 2024 form: minimum 2A-10B:C, under 10 pounds, mounted on its bracket within 10 feet of the kitchen in the exit path, visible and reachable","Homes with a low voltage fire alarm system must have it tested and approved by the alarm company before the inspection and show the alarm certification at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before settlement","amount":"$50"},{"label":"4 to 10 business days before settlement","amount":"$70"},{"label":"Less than 4 business days before settlement","amount":"$125"},{"label":"Re-inspection","amount":"$35"}]$j$::jsonb, $t$https://www.medfordlakes.com/DocumentCenter/View/119/Fire-Inspection-Application-PDF$t$, $t$https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy$t$, $j$[{"url":"https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/DocumentCenter/View/119/Fire-Inspection-Application-PDF","label":"Official source (medfordlakes.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The cost of the Smoke Detector/CO Detector Compliance Certificate is $50 if scheduled 10 days prior to change of occupancy, $70 if scheduled 4 to 10 days prior to change or $125 if scheduled less than 4 days prior.$t$, $t$5a082b4f17e2b5f8ff3735d3417177defb670496524212d85a49bd22e409320f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0321.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0321.json$t$, true),
  ($t$0324$t$, $t$Mount Laurel Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Mount Laurel Township Department of Community Development (Construction / Code)","Contact: Jennifer Parks, CCO questions and scheduling contact · 856-234-0001 ext. 1227 · jparks@mountlaurel.com","Apply: Fees are tiered by how early you apply: 11 or more days before closing is the lowest fee. The application must be submitted with payment before the inspection is scheduled; the office calls you to set the time.","How to apply: Fill out the CCO application (Ordinance 2021-8 form) and mail it or drop it off with payment at Mount Laurel Township, Attn: Jennifer Parks, 750 Centerton Road, 2nd Floor, Mount Laurel, NJ 08054. Emailed applications are NOT accepted. Payment by cash, check or money order only. The office calls to schedule the inspection (Monday to Friday, 8:30 to 11:30 AM or 11:30 AM to 2:30 PM).","All permits closed before approval (decks, pools, sheds, water heaters, furnace/HVAC, finished basements, electrical, plumbing, structural work)","Electric, gas and water on; panels, furnace and water heater accessible; furnace and water heater working and properly vented","Yard free of debris, high grass and hazards; roof, chimney, siding, gutters in good condition","Sidewalks, stairs, patios, walkways and driveways free of trip hazards","House numbers visible from the street, at least 4 inches high","Windows work with no broken or missing glass; entry doors have a working lockset and deadbolt; no double-key deadbolts or slide bolts","Handrail on stairs with 4 or more risers; guards where a walking surface is more than 30 inches above grade","Plumbing works with no leaks; hot and cold water; water temperature not over 120F","Bathroom has a working window or exhaust fan vented outside","Range anti-tip device where required","GFCI protection within 6 feet of sinks and at laundry sinks, garage and exterior outlets; covers on outlets, switches, junction boxes; panel cover with no open breaker spaces","Garage-to-house door solid wood, solid-core, steel or 20-minute rated; garage door opener plugged directly into an outlet (no extension cords); garage attic access fire rated (permit required)","Dryer vented outside with 4-inch rigid or semi-rigid metal duct (no plastic or foil); washer drains to approved drain","Pool barriers maintained; gates self-closing and self-latching, latch at least 54 inches high, opening away from pool","Any other health or safety hazard found by the inspector must be fixed","Also: Open permits must be closed: All required permits must be obtained and closed before CCO approval. Construction Department 856-234-9686.","Also: Rental registration if the buyer will rent: If the property will be a rental, it must be registered with the Township within 14 days of the closing date (Code Chapter 121).","Also: Fire department smoke/CO certificate: Smoke certificate required from the Fire Department; schedule at mlfd.org."]$j$::jsonb, $j$[{"label":"Initial inspection, requested 11 or more days before closing","amount":"$75.00"},{"label":"Inspection requested 4 to 10 days before closing","amount":"$100"},{"label":"Inspection requested 3 days or less before closing","amount":"$125"},{"label":"Discount: low/moderate income deed-restricted home or primary owner aged 65+","amount":"fifty percent (50%)"},{"label":"Re-inspection (waived if within 30 days and all items fixed)","amount":"$25.00"}]$j$::jsonb, $t$https://www.mountlaurel.com/CCO%20APPLICATION%202nd%20floor.pdf?t=202603171035570$t$, $t$https://www.mountlaurel.com/department/community_development___construction/new_page.php$t$, $j$[{"url":"https://www.mountlaurel.com/Document%20Center/Department/Community%20Development%20Construction/Forms/Housing%20Inspection%20List%20final.pdf?t=202106251245530","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/CCO%20APPLICATION%202nd%20floor.pdf?t=202603171035570","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/Mount_Laurel_Municipal_CCO_Checklist.pdf?t=202606101127590","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/department/community_development___construction/new_page.php","label":"Official source (mountlaurel.com)"}]$j$::jsonb, $t$REQUIREMENTS FOR CERTIFICATE OF CONTINUED OCCUPANCY (C.C.O.) For Resale of ALL Residential Homes$t$, $t$5f116d833148fbac71c2af4f1d995dc8b87e0cd18667401ffb8bb54bb4d11982$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0324.json$t$, true),
  ($t$0328$t$, $t$Pemberton Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency for Pemberton Borough) (NJ DCA, state)","Contact: Louis Kilmer, Deputy Division Director · (609) 633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before the closing date for the lowest fee.","How to apply: Apply online through the NJ DCA Fire Safety portal (smoke certificate application). Pay by e-check or credit card before submitting. A valid email address is required; the certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. All-electric homes with no CO requirement should email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 8/17/2026: Louis Kilmer · (609)633-6132","State certificate is now called the Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Secondary Power Source Identification Label Compliance (CSACMASPSIL); homes with a generator, solar or battery storage need the power source label","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Pemberton Borough$t$, $t$cc039b668d20cc6050d9b5c46d1baf270f9337aeee195c02c29b7c272c49ae5f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":9,"q_ok":6,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0328.json$t$, true),
  ($t$0330$t$, $t$Riverside Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Riverside Township Fire Official (municipal fire code enforcing agency) (town fire bureau)","Contact: Robert Yearly, Fire Official; Fire Subcode Official, Fire Inspector · 856-461-1460","How to apply: No separate smoke/CO certificate form or fee was found on the township website. The state directory lists Riverside Township, 237 S. Pavilion Ave, (856) 461-1460 for smoke detector compliance. The resale housing inspection also checks smoke alarms, CO alarms and the extinguisher. Call 856-461-1460 to confirm how the certificate is issued.","Fire official in the NJ state directory (town), updated 3/5/2026: Robert Yearly · (856) 461-1460 · robertyearly@comcast.net","Smoke alarms on each floor, and smoke and CO alarms within 10 feet of bedrooms; 10-year battery recommended (township 2019 housing checklist)","Fire extinguisher (checklist says \"210ABC\") mounted on the wall in the kitchen no higher than 5 feet (2019 checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://riversidetwp.org/construction-and-zoning-office/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://riversidetwp.org/construction-and-zoning-office/","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2021/11/1HOUSING-INSPECTION-CHECKLIST-Copy.pdf","label":"Official source (riversidetwp.org)"}]$j$::jsonb, $t$M Riverside Township$t$, $t$4e3b3263882717b847e377b4a2f6b497f9cc2c9912eab8224d668f6c89fe9c1f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0330.json$t$, true)
